// === Code node "Leer respuesta de Claude" ===
const r = $input.item.json;
if (r.stop_reason === 'refusal') throw new Error('Claude rechazó el pedido: revisar el video a mano');
const bloque = (r.content || []).find(b => b.type === 'text');
if (!bloque) throw new Error('Claude no devolvió texto');
const d = JSON.parse(bloque.text);
const cfg = $('Config La Pulpe').item.json;
const hashtags = [...new Set([...(cfg.hashtags_base || []), ...(d.hashtags || [])])].join(' ');
const limpio = String(d.titulo || 'reel').replace(/[\\/:*?"<>|]/g, '').slice(0, 60).trim();
return { json: {
  titulo: d.titulo,
  gancho: d.gancho,
  caption: d.caption,
  hashtags,
  nombre_archivo: `${cfg.fecha} - ${limpio}`,
}};

// === Code node "Armar texto para publicar" ===
const c = $('Leer respuesta de Claude').item.json;
const cfg = $('Config La Pulpe').item.json;
const txt = [
  `TÍTULO: ${c.titulo}`,
  `TEXTO PARA LA PORTADA: ${c.gancho}`,
  '',
  'CAPTION (copiar y pegar):',
  c.caption,
  '',
  c.hashtags,
  '',
  `Video original: ${cfg.file_name}`,
].join('\n');
return { json: {}, binary: { data: {
  data: Buffer.from(txt, 'utf8').toString('base64'),
  mimeType: 'text/plain',
  fileName: `${c.nombre_archivo}.txt`,
}}};
